package main
import("net/http";"encoding/json";"os";"path/filepath";"strconv";"sync")
var mu sync.Mutex
func main(){http.HandleFunc("/",func(w http.ResponseWriter,r *http.Request){w.Header().Set("Content-Type","text/html");w.Write([]byte("<!doctype html><html><title>Go counter</title><h1>Go counter</h1><p id=\"value\"></p><button id=\"add\">Add one</button><script>async function refresh(){document.querySelector(\"#value\").textContent=(await(await fetch(\"/api/count\")).json()).count}document.querySelector(\"#add\").onclick=async()=>{await fetch(\"/api/count\",{method:\"POST\"});refresh()};refresh()</script></html>"))});http.HandleFunc("/api/count",func(w http.ResponseWriter,r *http.Request){mu.Lock();defer mu.Unlock();path:=filepath.Join(os.Getenv("PODS_APP_DATA"),"count");b,_:=os.ReadFile(path);n,_:=strconv.Atoi(string(b));if r.Method=="POST"{n++;if err:=os.WriteFile(path,[]byte(strconv.Itoa(n)),0600);err!=nil{http.Error(w,"write failed",500);return}};w.Header().Set("Content-Type","application/json");json.NewEncoder(w).Encode(map[string]int{"count":n})});http.ListenAndServe(":"+os.Getenv("PORT"),nil)}
